-- DED complexes:  the 48 rated complexes of Crucible, 1/10 to 10/10.
--  utils/ded/gen_ded_sql.py writes this (the sources and picks are listed there)
--  - archetype 10 (rated), difficulty = the DED rating, security by rating:  1-5 high and low-sec, 6 low and
--    null, 7-10 null.  AnomalyMgr picks the region's pirate faction
--  - an entry gate and 2-5 pockets.  the gates take what the rating allows;  the overseer in the last pocket
--    drops Overseer's Personal Effects and its death completes the complex
-- +migrate Up
